/// One message as the chat screen shows it.
class ChatMessage {
  final String eventId;
  final String sender;

  /// None = could not be opened (key missing).
  final String? body;
  final bool wasEncrypted;

  /// Milliseconds since 1970 (server time).
  final BigInt ts;
  final bool mine;

  /// "text", "image", "video", "audio", "file", "sticker" or "locked".
  final String kind;

  /// The message this one answers, if any.
  final String? replyTo;

  /// First message of its thread ("스레드로 답장").
  final String? threadRoot;

  /// 주제 (tip 527): topic id from inside the encrypted content; None = 일반.
  final String? topic;
  final bool edited;

  /// When it was last changed (ms), and the words as first sent.
  final BigInt? editedAt;
  final String? firstBody;
  final List<ReactionRow> reactions;

  /// Disappears at this time (ms), if the chat has a timer.
  final BigInt? expiresAt;

  /// Photo/video that opens only once, and whether it was opened.
  final bool viewOnce;
  final bool opened;
  final bool forwarded;
  final LinkPreviewRow? preview;
  final VoiceRow? voice;

  /// 움직이는 사진: play style and clip length.
  final LiveRow? live;
  final PollRow? poll;
  final bool bubble;
  final CallRow? call;

  /// Words under a photo, video or file.
  final String? caption;

  /// File size in bytes (photo, video, file, voice), when the sender wrote it.
  final BigInt? size;
  final ChecklistRow? checklist;
  final MeetupRow? meetup;

  /// Shared contact's user id (kind "contact").
  final String? contact;

  /// FAQ, guide, links, formatted post, giveaway, form, check-in.
  final CardRow? card;

  /// 부분 인용 (tip 399): the picked words; with `quote_name` and no
  /// `reply_to` they were copied from another chat.
  final String? quote;
  final String? quoteName;

  /// 설명 위로 (tip 452).
  final bool captionAbove;

  /// The file was swapped by an edit: download it from this event.
  final String? mediaFrom;
  final bool mediaChanged;

  /// 보내는 이름 (tips 472 + 310): who it was sent as (JSON), if not me.
  final String? postAs;

  const ChatMessage({
    required this.eventId,
    required this.sender,
    this.body,
    required this.wasEncrypted,
    required this.ts,
    required this.mine,
    required this.kind,
    this.replyTo,
    this.threadRoot,
    this.topic,
    required this.edited,
    this.editedAt,
    this.firstBody,
    required this.reactions,
    this.expiresAt,
    required this.viewOnce,
    required this.opened,
    required this.forwarded,
    this.preview,
    this.voice,
    this.live,
    this.poll,
    required this.bubble,
    this.call,
    this.caption,
    this.size,
    this.checklist,
    this.meetup,
    this.contact,
    this.card,
    this.quote,
    this.quoteName,
    required this.captionAbove,
    this.mediaFrom,
    required this.mediaChanged,
    this.postAs,
  });

  @override
  int get hashCode =>
      eventId.hashCode ^
      sender.hashCode ^
      body.hashCode ^
      wasEncrypted.hashCode ^
      ts.hashCode ^
      mine.hashCode ^
      kind.hashCode ^
      replyTo.hashCode ^
      threadRoot.hashCode ^
      topic.hashCode ^
      edited.hashCode ^
      editedAt.hashCode ^
      firstBody.hashCode ^
      reactions.hashCode ^
      expiresAt.hashCode ^
      viewOnce.hashCode ^
      opened.hashCode ^
      forwarded.hashCode ^
      preview.hashCode ^
      voice.hashCode ^
      live.hashCode ^
      poll.hashCode ^
      bubble.hashCode ^
      call.hashCode ^
      caption.hashCode ^
      size.hashCode ^
      checklist.hashCode ^
      meetup.hashCode ^
      contact.hashCode ^
      card.hashCode ^
      quote.hashCode ^
      quoteName.hashCode ^
      captionAbove.hashCode ^
      mediaFrom.hashCode ^
      mediaChanged.hashCode ^
      postAs.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ChatMessage &&
          runtimeType == other.runtimeType &&
          eventId == other.eventId &&
          sender == other.sender &&
          body == other.body &&
          wasEncrypted == other.wasEncrypted &&
          ts == other.ts &&
          mine == other.mine &&
          kind == other.kind &&
          replyTo == other.replyTo &&
          threadRoot == other.threadRoot &&
          topic == other.topic &&
          edited == other.edited &&
          editedAt == other.editedAt &&
          firstBody == other.firstBody &&
          reactions == other.reactions &&
          expiresAt == other.expiresAt &&
          viewOnce == other.viewOnce &&
          opened == other.opened &&
          forwarded == other.forwarded &&
          preview == other.preview &&
          voice == other.voice &&
          live == other.live &&
          poll == other.poll &&
          bubble == other.bubble &&
          call == other.call &&
          caption == other.caption &&
          size == other.size &&
          checklist == other.checklist &&
